UPDATE Bin
SET Tonnes = Tonnes * 0.5
WHERE Grain = 'barley' AND Sealed = FALSE;

UPDATE Sensor
SET Room = 'Lab 2'
WHERE Room = 'Lab B';

CREATE TABLE Seedling (
  Tray INTEGER PRIMARY KEY,
  Species VARCHAR(18) NOT NULL,
  Height REAL
);

UPDATE Seedling
SET Height = Height * 1.1, Potted = TRUE
WHERE Species = 'birch';
